import { AssetManager } from '../asset-manager';
import { Sound } from '../sounds';
import { IHowlSoundAssetConfig, ILegacySoundAssetConfig, ISoundAssetConfig } from '../types';

export function filterHowlerAssets(assetMap: ISoundAssetConfig[], isLazyLoad: boolean) {
    return assetMap
        .filter((asset) => isLazyLoad || !asset.isLazyLoad)
        .filter((asset) => AssetManager.sounds[asset.name] === undefined);
}

export class SoundLoader {

    public static load(baseUrl: string, config: ISoundAssetConfig[], isLazyLoad: boolean): Promise<void[]> {
        const itemsToLoad = filterHowlerAssets(config, isLazyLoad);
        return this.loadSounds(baseUrl, itemsToLoad);
    }

    protected static srcToSrcs(srcArgs: string | string[]) {
        const srcArray = typeof srcArgs === 'string' ? [srcArgs] : srcArgs;
        const reducedSrcs = srcArray.reduce((totalSrc, src) => {
            const match = /\.{([\w,]+)}$/.exec(src);
            if (match) {
                const fileExtensions = match[1].split(',');
                const originalFileName = src.slice(0, match.index);
                return [...totalSrc, ...fileExtensions.map((extension) => {
                    return `${originalFileName}.${extension}`;
                })];
            }
            return [...totalSrc, src];
        }, [] as string[]);
        if (reducedSrcs.length > 1) {
            return reducedSrcs;
        }
        return reducedSrcs[0];
    }

    private static pixiSpritesToHowlerSprite(sprites: { [spriteName: string]: { start: number, end: number } }) {
        const howlSprites: { [spriteName: string]: [number, number] } = {};
        for (const spriteName in sprites) {
            const { start, end } = sprites[spriteName];
            const startInSeconds = start * 1000;
            const endInSeconds = end * 1000;
            const durationInSeconds = endInSeconds - startInSeconds;
            howlSprites[spriteName] = [startInSeconds, durationInSeconds];
        }
        return howlSprites;
    }

    private static loadSounds(baseUrl: string, config: ISoundAssetConfig[]) {
        const sounds = config.map((soundConfig) => {
            const isHowl = (soundConfig as object).hasOwnProperty('src');
            const isLegacy = !isHowl && (soundConfig as object).hasOwnProperty('url');
            if (isHowl) {
                const howlConfig = soundConfig as unknown as IHowlSoundAssetConfig;
                howlConfig.src = SoundLoader.srcToSrcs(howlConfig.src);
                return new Sound(howlConfig);
            } else if (isLegacy) {
                const legacyConfig = soundConfig as unknown as ILegacySoundAssetConfig;
                if (!!legacyConfig.sprites) {
                    legacyConfig.sprite = SoundLoader.pixiSpritesToHowlerSprite(legacyConfig.sprites);
                    delete legacyConfig.sprites;
                }
                return new Sound({
                    ...soundConfig,
                    src: SoundLoader.srcToSrcs(`${baseUrl}${legacyConfig.url}`)
                });
            } else {
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const config = soundConfig as unknown as any;
                throw new Error(`Invalid sound config for "${config.name}". Must contain either a "src" property for Howl configs or a "url" property for legacy configs.`);
            }
        });
        sounds.forEach((sound) => {
            AssetManager.sounds[sound.name] = sound;
        });
        return Promise.all(sounds.map((sound) => sound.load()));
    }
}